import{_ as i,C as l,o as n,c as d,ag as a,E as o,j as t,a as r}from"./chunks/framework.CtWPcAmt.js";const _=JSON.parse('{"title":"Seller Attributes","description":"","frontmatter":{},"headers":[],"relativePath":"sellers/seller-attributes.md","filePath":"sellers/seller-attributes.md","lastUpdated":1787558413000}'),g={name:"sellers/seller-attributes.md"};function u(c,e,p,h,m,b){const s=l("ImagePopup");return n(),d("div",null,[e[0]||(e[0]=a('<h1 id="seller-attributes" tabindex="-1">Seller Attributes <a class="header-anchor" href="#seller-attributes" aria-label="Permalink to &quot;Seller Attributes&quot;">​</a></h1><p>Seller Attributes are the building blocks of a seller&#39;s profile and configuration. Just as product attributes define a product form, seller attributes define the fields that make up a seller — from business details and social links to commission and Magic AI settings. The admin manages them, and controls how they&#39;re laid out on the seller form.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>What seller attributes are and where they&#39;re used</li><li>How to create an attribute, field by field</li><li>How to arrange attributes into the seller form</li></ul></div><h2 id="the-attributes-list" tabindex="-1">The attributes list <a class="header-anchor" href="#the-attributes-list" aria-label="Permalink to &quot;The attributes list&quot;">​</a></h2><p>In the admin panel, go to <strong>Marketplace → Sellers → Seller Attributes</strong>. The list shows every attribute with its <strong>code</strong>, <strong>name</strong>, <strong>type</strong>, and whether it&#39;s <strong>required</strong>, <strong>unique</strong>, <strong>locale-based</strong>, or <strong>channel-based</strong>.</p>',5)),o(s,{src:"/images/seller-attributes/seller-attributes.png",alt:"Admin seller attributes list"}),e[1]||(e[1]=t("p",null,[r("The two header buttons are "),t("strong",null,"Create Seller Attribute"),r(" and "),t("strong",null,"Mapping"),r(".")],-1)),e[2]||(e[2]=t("h2",{id:"creating-an-attribute",tabindex:"-1"},[r("Creating an attribute "),t("a",{class:"header-anchor",href:"#creating-an-attribute","aria-label":'Permalink to "Creating an attribute"'},"​")],-1)),e[3]||(e[3]=t("p",null,[r("Select "),t("strong",null,"Create Seller Attribute"),r(" and define the field:")],-1)),o(s,{src:"/images/seller-attributes/attribute-create.png",alt:"Create seller attribute form"}),e[4]||(e[4]=a('<ul><li><strong>Admin name</strong> and per-locale <strong>name</strong> — the internal and displayed labels.</li><li><strong>Code</strong> — the unique identifier used in the system.</li><li><strong>Type</strong> — the input type: text, textarea, boolean, select, multiselect, date, datetime, image, file, checkbox.</li><li><strong>Validation</strong> and <strong>regex</strong>, an optional <strong>default value</strong>, and a rich-text <strong>editor</strong> toggle.</li><li>Flags: <strong>required</strong>, <strong>unique</strong>, <strong>value per locale</strong>, <strong>value per channel</strong>, and visibility toggles — <strong>on sign up</strong>, <strong>on profile</strong>, and <strong>on public</strong> profile.</li><li><strong>Options</strong> — for select / multiselect / checkbox types, the list of choices (each with a label and position).</li></ul><p>Only <strong>user-defined</strong> attributes can be deleted; the system attributes the marketplace ships with are protected.</p><h2 id="mapping-attributes-to-the-form" tabindex="-1">Mapping attributes to the form <a class="header-anchor" href="#mapping-attributes-to-the-form" aria-label="Permalink to &quot;Mapping attributes to the form&quot;">​</a></h2><p>The <strong>Mapping</strong> screen arranges attributes into the two-column seller form: which <strong>groups</strong> (General, Description, Policies, Meta Description, Address, Social Links, Settings, …) sit in which <strong>column</strong>, and the <strong>order</strong> of attributes within each group. This is exactly the layout that appears on the <a href="/sellers/seller-management#editing-a-seller">seller edit form</a> and sign-up.</p><p>You can also change the groups themselves:</p><ul><li><strong>Add Group</strong> — create a new group with a <strong>name</strong> and a <strong>code</strong>, and choose the <strong>column</strong> it sits in.</li><li><strong>Rename a group</strong> — double-click its heading to edit it.</li><li><strong>Delete Group</strong> — remove a group you no longer need.</li></ul><h2 id="attributes-that-ship-by-default" tabindex="-1">Attributes that ship by default <a class="header-anchor" href="#attributes-that-ship-by-default" aria-label="Permalink to &quot;Attributes that ship by default&quot;">​</a></h2><p>The marketplace comes with a full set of seller attributes, including:</p><ul><li><strong>Commission</strong> — <code>commission_enabled</code> and <code>commission_percentage</code> set a seller&#39;s <a href="/payments/commission-management">commission</a>.</li><li><strong>Magic AI</strong> — <code>magic_ai_enabled</code> and <code>magic_ai_seller_limit</code> govern a seller&#39;s <a href="/catalog/magic-ai">Magic AI</a> access and quota.</li><li><strong>Selling controls</strong> — <code>allowed_product_types</code> and <code>min_order_amount</code>.</li><li><strong>Profile &amp; marketing</strong> — business details, policies, and social links (<code>facebook</code>, <code>instagram</code>, <code>youtube</code>, <code>google_analytics_id</code>).</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Add a seller attribute whenever you need a new piece of information or a new per-seller control — it becomes available on the seller form (and, if you choose, at sign-up) for every seller, without any code changes.</p></div>',10))])}const y=i(g,[["render",u]]);export{_ as __pageData,y as default};
